using System.Globalization;
using System.Reflection;

[AttributeUsage(AttributeTargets.Method)]
public class FactAttribute : Attribute { public string? Skip { get; set; } }

[AttributeUsage(AttributeTargets.Method)]
public class TheoryAttribute : Attribute { }

[AttributeUsage(AttributeTargets.Method, AllowMultiple = true)]
public class InlineDataAttribute(params object?[] data) : Attribute { public object?[] Data { get; } = data; }

public record TestResult(string Name, string Outcome, string? Message);

public static class Runner
{
    public static List<TestResult> Run(Type testClass)
    {
        var results = new List<TestResult>();
        var methods = testClass.GetMethods(BindingFlags.Public | BindingFlags.Instance)
            .Where(m => m.GetCustomAttribute<FactAttribute>() != null || m.GetCustomAttribute<TheoryAttribute>() != null)
            .OrderBy(m => m.Name, StringComparer.Ordinal);

        foreach (var method in methods)
        {
            if (method.GetCustomAttribute<FactAttribute>() is FactAttribute fact)
            {
                if (fact.Skip != null) results.Add(new(method.Name, "skipped", fact.Skip));
                else results.Add(RunOne(testClass, method, method.Name, Array.Empty<object?>()));
                continue;
            }
            foreach (var data in method.GetCustomAttributes<InlineDataAttribute>())
            {
                string name = $"{method.Name}({string.Join(", ", data.Data.Select(Show))})";
                int expected = method.GetParameters().Length;
                if (data.Data.Length != expected) results.Add(new(name, "failed", $"expected {expected} arguments"));
                else results.Add(RunOne(testClass, method, name, data.Data));
            }
        }
        return results;
    }

    private static TestResult RunOne(Type testClass, MethodInfo method, string name, object?[] args)
    {
        try
        {
            object instance = Activator.CreateInstance(testClass)!;
            object? returned = method.Invoke(instance, args);
            if (returned is Task task) task.GetAwaiter().GetResult();
            return new(name, "passed", null);
        }
        catch (TargetInvocationException e) when (e.InnerException != null)
        {
            return new(name, "failed", e.InnerException.Message);
        }
        catch (Exception e)
        {
            return new(name, "failed", e.Message);
        }
    }

    private static string Show(object? value) => value switch
    {
        null => "null",
        string s => $"\"{s}\"",
        bool b => b ? "true" : "false",
        IFormattable f => f.ToString(null, CultureInfo.InvariantCulture),
        _ => value.ToString() ?? "",
    };
}

