Test("facts pass, fail and skip", () =>
{
    var results = Runner.Run(typeof(SampleTests));
    CheckEq(results.Select(r => $"{r.Name} {r.Outcome}"), new[]
    {
        "Adds passed",
        "AsyncFails failed",
        "AsyncWorks passed",
        "Broken failed",
        "Doubles(2, 4) passed",
        "Doubles(3, 7) failed",
        "Doubles(1) failed",
        "Greets(\"Ada\", true) passed",
        "Later skipped",
        "Rates(0.5) passed",
    });
});

Test("messages", () =>
{
    var r = Runner.Run(typeof(SampleTests)).ToDictionary(x => x.Name);
    CheckEq(r["Broken"].Message, "boom");
    CheckEq(r["AsyncFails"].Message, "async boom");
    CheckEq(r["Doubles(3, 7)"].Message, "3 * 2 is 6, not 7");
    CheckEq(r["Doubles(1)"].Message, "expected 2 arguments");
    CheckEq(r["Later"].Message, "not ready");
    CheckEq(r["Adds"].Message, null);
});

Test("a fresh instance for every test", () =>
{
    var results = Runner.Run(typeof(CounterTests));
    CheckEq(results.Select(x => x.Outcome), new[] { "passed", "passed" });
    CheckEq(Runner.Run(typeof(string)).Count, 0);
});

