public class SampleTests
{
    [Fact] public void Adds() { if (1 + 1 != 2) throw new Exception("math is broken"); }
    [Fact] public void Broken() => throw new InvalidOperationException("boom");
    [Fact(Skip = "not ready")] public void Later() => throw new Exception("should not run");
    [Fact] public async Task AsyncWorks() => await Task.Delay(1);
    [Fact] public async Task AsyncFails() { await Task.Delay(1); throw new Exception("async boom"); }

    [Theory]
    [InlineData(2, 4)]
    [InlineData(3, 7)]
    [InlineData(1)]
    public void Doubles(int x, int expected) { if (x * 2 != expected) throw new Exception($"{x} * 2 is {x * 2}, not {expected}"); }

    [Theory, InlineData("Ada", true)]
    public void Greets(string name, bool polite) { if (!polite || name.Length == 0) throw new Exception("rude"); }

    [Theory, InlineData(0.5)]
    public void Rates(double r) { if (r <= 0) throw new Exception("bad rate"); }

    public void NotATest() => throw new Exception("helper methods must not run");
}

public class CounterTests
{
    private int _count;
    [Fact] public void First() { _count++; if (_count != 1) throw new Exception($"count is {_count}"); }
    [Fact] public void Second() { _count++; if (_count != 1) throw new Exception($"count is {_count}"); }
}
